/**
 * Get the RTD name for a ride type int.
 */
function getRideTypeName(rideType: number): string {
    return RIDE_TYPE_NAMES[rideType] || "";
}

/**
 * Check whether a ride type allows a given TrackGroup.
 */
function isTrackGroupEnabled(rideTypeName: string, trackGroup: number, includeExtras: boolean): boolean {
    var enabled = RIDE_TYPE_ENABLED_GROUPS[rideTypeName];
    if (enabled && enabled[trackGroup]) {
        return true;
    }
    if (includeExtras) {
        var extras = RIDE_TYPE_EXTRA_GROUPS[rideTypeName];
        if (extras && extras[trackGroup]) {
            return true;
        }
    }
    return false;
}

/**
 * Get the TrackGroup for a given TrackElemType.
 */
function getTrackGroup(trackElemType: number): number {
    return TRACK_ELEM_TO_GROUP[trackElemType];
}

/**
 * Get all enabled TrackGroup values for a ride type as an array.
 */
function getEnabledGroups(rideTypeName: string, includeExtras: boolean): number[] {
    var result: number[] = [];
    var enabled = RIDE_TYPE_ENABLED_GROUPS[rideTypeName];
    if (enabled) {
        for (var k in enabled) {
            result.push(parseInt(k, 10));
        }
    }
    if (includeExtras) {
        var extras = RIDE_TYPE_EXTRA_GROUPS[rideTypeName];
        if (extras) {
            for (var k in extras) {
                result.push(parseInt(k, 10));
            }
        }
    }
    return result;
}

/**
 * Compute valid next track segments for a ride type given the current slope and bank.
 * Filters getAllTrackSegments() by enabled track groups and slope/bank compatibility.
 */
function getValidNextSegments(rideType: number, endSlope: number, endBank: number, includeExtras: boolean): number[] {
    var rtdName = getRideTypeName(rideType);
    if (!rtdName) {
        return [];
    }
    var segments = context.getAllTrackSegments();
    var result: number[] = [];
    for (var i = 0; i < segments.length; i++) {
        var seg = segments[i];
        // Filter by track group enabled for this ride type
        var group = seg.trackGroup;
        if (!isTrackGroupEnabled(rtdName, group, includeExtras)) {
            continue;
        }
        // Filter by slope/bank compatibility: segment's begin must match current end
        if (seg.beginSlope !== endSlope || seg.beginBank !== endBank) {
            continue;
        }
        result.push(seg.type);
    }
    return result;
}

export {
    getRideTypeName,
    isTrackGroupEnabled,
    getTrackGroup,
    getEnabledGroups,
    getValidNextSegments,
    RIDE_TYPE_NAMES,
    RIDE_TYPE_ENABLED_GROUPS,
    RIDE_TYPE_EXTRA_GROUPS,
    TRACK_ELEM_TO_GROUP,
};
